export function createApp(store) {
  return async function handle(req, res) {
    try {
      const url = new URL(req.url, `http://${req.headers.host ?? "localhost"}`);
      const bookMatch = url.pathname.match(/^\/books\/([A-Za-z0-9_-]+)$/);
      const finishMatch = url.pathname.match(/^\/books\/([A-Za-z0-9_-]+)\/finish$/);

      if (req.method === "GET" && url.pathname === "/") {
        return send(res, 200, homePage(store.list()));
      }

      if (req.method === "POST" && url.pathname === "/books") {
        let form = {};
        try {
          form = await readForm(req);
          const book = await store.add(form);
          return redirect(res, `/books/${book.id}`);
        } catch (err) {
          if (!(err instanceof ValidationError)) throw err;
          return send(res, 400, homePage(store.list(), { error: err.message, values: form }));
        }
      }

      if (req.method === "GET" && bookMatch) {
        const book = store.get(bookMatch[1]);
        if (!book) return send(res, 404, notFoundPage());
        return send(res, 200, bookPage(book, `${url.origin}/books/${book.id}`));
      }

      if (req.method === "POST" && finishMatch) {
        const book = await store.markFinished(finishMatch[1]);
        if (!book) return send(res, 404, notFoundPage());
        // Go back to wherever the button was pressed (list or book page).
        const back = req.headers.referer ? new URL(req.headers.referer, url).pathname : "/";
        return redirect(res, back === `/books/${book.id}` ? back : "/");
      }

      return send(res, 404, notFoundPage());
    } catch (err) {
      console.error(err);
      if (!res.headersSent) send(res, 500, "<p>Something went wrong.</p>");
      else res.end();
    }
  };
}
