    await start();

    const detail = await (await fetch(base + location)).text();
    expect(detail).toContain("Persist");
    expect(detail).toContain("keep me");
    expect(detail).toContain("Finished");

    const saved = JSON.parse(await readFile(dataFile, "utf8"));
    expect(saved).toHaveLength(1);
    expect(saved[0]).toMatchObject({ title: "Persist", status: "finished" });
  });

  it("rejects a book without a title and keeps what was typed", async () => {
    const res = await post("/books", { title: "  ", author: "Anon", notes: "draft" });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain("title is required");
    expect(html).toContain('value="Anon"');
    expect(html).toContain("draft");
  });

  it("escapes HTML in user input", async () => {
    const location = await addBook({ title: "<script>alert(1)</script>", author: "x", notes: "<b>hi</b>" });
    const detail = await (await fetch(base + location)).text();
    expect(detail).not.toContain("<script>alert(1)</script>");
    expect(detail).toContain("&lt;script&gt;");
    expect(detail).toContain("&lt;b&gt;hi&lt;/b&gt;");
  });

  it("404s for unknown books", async () => {
    expect((await fetch(base + "/books/nope")).status).toBe(404);
    expect((await post("/books/nope/finish", {})).status).toBe(404);
  });

  it("refuses to start with a corrupt data file instead of overwriting it", async () => {
    await writeFile(dataFile, "{not json");
    await expect(createStore(dataFile)).rejects.toThrow(/Could not read/);
    expect(await readFile(dataFile, "utf8")).toBe("{not json");
  });
});
